package main

import (
	"context"
	"errors"
	"sync"
)

var (
	ErrPoolClosed    = errors.New("pool is closed")
	ErrInvalidWorkers = errors.New("worker count must be > 0")
)

// Task represents a unit of work submitted to the pool.
type Task struct {
	Fn     func(ctx context.Context) (any, error)
	Result chan TaskResult
}

// TaskResult holds the output of a completed task.
type TaskResult struct {
	Value any
	Err   error
}

// LRUCache is a thread pool that executes tasks concurrently across a fixed
// number of worker goroutines. Despite the name (per user request), it is a
// thread pool, not an LRU cache.
type LRUCache struct {
	tasks   chan Task
	wg      sync.WaitGroup
	once    sync.Once
	ctx     context.Context
	cancel  context.CancelFunc
	closed  chan struct{}
}

// NewLRUCache creates a thread pool with the given number of workers.
// Each worker processes tasks from a shared queue concurrently.
func NewLRUCache(workers int) (*LRUCache, error) {
	if workers <= 0 {
		return nil, ErrInvalidWorkers
	}

	ctx, cancel := context.WithCancel(context.Background())
	p := &LRUCache{
		tasks:  make(chan Task, workers*10),
		ctx:    ctx,
		cancel: cancel,
		closed: make(chan struct{}),
	}

	for i := 0; i < workers; i++ {
		p.wg.Add(1)
		go p.worker(i)
	}

	return p, nil
}

func (p *LRUCache) worker(id int) {
	defer p.wg.Done()
	for {
		select {
		case <-p.ctx.Done():
			return
		case task, ok := <-p.tasks:
			if !ok {
				return
			}
			val, err := task.Fn(p.ctx)
			task.Result <- TaskResult{Value: val, Err: err}
		}
	}
}

// Submit sends a task to the pool and returns the result once a worker picks
// it up. Returns ErrPoolClosed if the pool has been shut down.
func (p *LRUCache) Submit(ctx context.Context, fn func(ctx context.Context) (any, error)) (any, error) {
	select {
	case <-p.closed:
		return nil, ErrPoolClosed
	default:
	}

	resultCh := make(chan TaskResult, 1)
	task := Task{Fn: fn, Result: resultCh}

	select {
	case <-p.closed:
		return nil, ErrPoolClosed
	case p.tasks <- task:
	}

	select {
	case <-ctx.Done():
		return nil, ctx.Err()
	case res := <-resultCh:
		return res.Value, res.Err
	}
}

// SubmitAsync submits a task and returns a channel that will receive the result.
func (p *LRUCache) SubmitAsync(ctx context.Context, fn func(ctx context.Context) (any, error)) <-chan TaskResult {
	resultCh := make(chan TaskResult, 1)

	go func() {
		val, err := p.Submit(ctx, fn)
		resultCh <- TaskResult{Value: val, Err: err}
	}()

	return resultCh
}

// Shutdown gracefully stops the pool, waiting for all queued tasks to complete.
func (p *LRUCache) Shutdown() {
	p.once.Do(func() {
		close(p.closed)
		close(p.tasks)
		p.wg.Wait()
	})
}

// ShutdownNow stops the pool immediately, cancelling in-flight work.
func (p *LRUCache) ShutdownNow() {
	p.once.Do(func() {
		close(p.closed)
		p.cancel()
		close(p.tasks)
		p.wg.Wait()
	})
}

// Workers returns the number of workers (for testing).
func (p *LRUCache) Workers() int {
	// We don't store this, but the pool was created with N workers.
	// The WaitGroup tracks them. This is a convenience for tests.
	return -1 // not tracked; tests use known values
}

package main

import (
	"context"
	"errors"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

func TestNewLRUCache_InvalidWorkers(t *testing.T) {
	for _, n := range []int{0, -1, -100} {
		_, err := NewLRUCache(n)
		if !errors.Is(err, ErrInvalidWorkers) {
			t.Errorf("NewLRUCache(%d): expected ErrInvalidWorkers, got %v", n, err)
		}
	}
}

func TestSubmit_SingleTask(t *testing.T) {
	pool, err := NewLRUCache(2)
	if err != nil {
		t.Fatal(err)
	}
	defer pool.Shutdown()

	val, err := pool.Submit(context.Background(), func(ctx context.Context) (any, error) {
		return 42, nil
	})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if val != 42 {
		t.Fatalf("expected 42, got %v", val)
	}
}

func TestSubmit_TaskError(t *testing.T) {
	pool, err := NewLRUCache(1)
	if err != nil {
		t.Fatal(err)
	}
	defer pool.Shutdown()

	expectedErr := errors.New("task failed")
	_, err = pool.Submit(context.Background(), func(ctx context.Context) (any, error) {
		return nil, expectedErr
	})
	if !errors.Is(err, expectedErr) {
		t.Fatalf("expected %v, got %v", expectedErr, err)
	}
}

func TestSubmit_ParallelExecution(t *testing.T) {
	pool, err := NewLRUCache(4)
	if err != nil {
		t.Fatal(err)
	}
	defer pool.Shutdown()

	var active atomic.Int32
	var maxActive atomic.Int32

	task := func(ctx context.Context) (any, error) {
		cur := active.Add(1)
		// Track the max number of concurrent workers
		for {
			old := maxActive.Load()
			if cur <= old || maxActive.CompareAndSwap(old, cur) {
				break
			}
		}
		time.Sleep(50 * time.Millisecond)
		active.Add(-1)
		return nil, nil
	}

	const numTasks = 20
	results := make(chan TaskResult, numTasks)
	for i := 0; i < numTasks; i++ {
		go func() {
			val, err := pool.Submit(context.Background(), task)
			results <- TaskResult{Value: val, Err: err}
		}()
	}

	for i := 0; i < numTasks; i++ {
		r := <-results
		if r.Err != nil {
			t.Fatalf("task error: %v", r.Err)
		}
	}

	if maxActive.Load() < 2 {
		t.Errorf("expected parallel execution, max concurrent = %d", maxActive.Load())
	}
}

func TestSubmit_ManyTasks(t *testing.T) {
	pool, err := NewLRUCache(3)
	if err != nil {
		t.Fatal(err)
	}
	defer pool.Shutdown()

	var mu sync.Mutex
	sum := 0
	const n = 100

	var wg sync.WaitGroup
	wg.Add(n)
	for i := 0; i < n; i++ {
		go func(v int) {
			defer wg.Done()
			val, err := pool.Submit(context.Background(), func(ctx context.Context) (any, error) {
				return v, nil
			})
			if err != nil {
				t.Errorf("task %d: %v", v, err)
				return
			}
			mu.Lock()
			sum += val.(int)
			mu.Unlock()
		}(i)
	}
	wg.Wait()

	expected := n * (n - 1) / 2
	if sum != expected {
		t.Fatalf("expected sum %d, got %d", expected, sum)
	}
}

func TestSubmit_ContextCancellation(t *testing.T) {
	pool, err := NewLRUCache(1)
	if err != nil {
		t.Fatal(err)
	}
	defer pool.Shutdown()

	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()

	_, err = pool.Submit(ctx, func(ctx context.Context) (any, error) {
		time.Sleep(5 * time.Second) // longer than timeout
		return nil, nil
	})
	if !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("expected DeadlineExceeded, got %v", err)
	}
}

func TestSubmit_AfterShutdown(t *testing.T) {
	pool, err := NewLRUCache(2)
	if err != nil {
		t.Fatal(err)
	}
	pool.Shutdown()

	_, err = pool.Submit(context.Background(), func(ctx context.Context) (any, error) {
		return nil, nil
	})
	if !errors.Is(err, ErrPoolClosed) {
		t.Fatalf("expected ErrPoolClosed, got %v", err)
	}
}

func TestSubmitAsync(t *testing.T) {
	pool, err := NewLRUCache(2)
	if err != nil {
		t.Fatal(err)
	}
	defer pool.Shutdown()

	ch := pool.SubmitAsync(context.Background(), func(ctx context.Context) (any, error) {
		return "hello", nil
	})

	res := <-ch
	if res.Err != nil {
		t.Fatalf("unexpected error: %v", res.Err)
	}
	if res.Value != "hello" {
		t.Fatalf("expected hello, got %v", res.Value)
	}
}

func TestShutdown_CompletesPendingTasks(t *testing.T) {
	pool, err := NewLRUCache(2)
	if err != nil {
		t.Fatal(err)
	}

	var completed atomic.Int32
	for i := 0; i < 10; i++ {
		go func() {
			pool.Submit(context.Background(), func(ctx context.Context) (any, error) {
				time.Sleep(10 * time.Millisecond)
				completed.Add(1)
				return nil, nil
			})
		}()
	}

	time.Sleep(5 * time.Millisecond) // let tasks enqueue
	pool.Shutdown()

	if completed.Load() != 10 {
		t.Fatalf("expected 10 completed, got %d", completed.Load())
	}
}

func TestShutdownNow_CancelsContext(t *testing.T) {
	pool, err := NewLRUCache(2)
	if err != nil {
		t.Fatal(err)
	}

	var cancelled atomic.Bool
	go func() {
		pool.Submit(context.Background(), func(ctx context.Context) (any, error) {
			select {
			case <-ctx.Done():
				cancelled.Store(true)
			case <-time.After(5 * time.Second):
			}
			return nil, nil
		})
	}()

	time.Sleep(10 * time.Millisecond)
	pool.ShutdownNow()

	if !cancelled.Load() {
		t.Fatal("expected context to be cancelled by ShutdownNow")
	}
}

func TestShutdown_Idempotent(t *testing.T) {
	pool, err := NewLRUCache(2)
	if err != nil {
		t.Fatal(err)
	}
	pool.Shutdown()
	pool.Shutdown() // should not panic
}

func TestSubmit_Stress(t *testing.T) {
	if testing.Short() {
		t.Skip("skipping stress test in short mode")
	}

	pool, err := NewLRUCache(8)
	if err != nil {
		t.Fatal(err)
	}
	defer pool.Shutdown()

	const n = 1000
	var wg sync.WaitGroup
	wg.Add(n)

	var errCount atomic.Int32
	for i := 0; i < n; i++ {
		go func(v int) {
			defer wg.Done()
			val, err := pool.Submit(context.Background(), func(ctx context.Context) (any, error) {
				return v * 2, nil
			})
			if err != nil {
				errCount.Add(1)
				return
			}
			if val.(int) != v*2 {
				t.Errorf("expected %d, got %d", v*2, val)
			}
		}(i)
	}
	wg.Wait()

	if errCount.Load() > 0 {
		t.Fatalf("%d tasks returned errors", errCount.Load())
	}
}

func TestSubmit_ConcurrentShutdown(t *testing.T) {
	pool, err := NewLRUCache(4)
	if err != nil {
		t.Fatal(err)
	}

	var wg sync.WaitGroup
	wg.Add(10)
	for i := 0; i < 10; i++ {
		go func() {
			defer wg.Done()
			pool.Submit(context.Background(), func(ctx context.Context) (any, error) {
				time.Sleep(5 * time.Millisecond)
				return nil, nil
			})
		}()
	}

	time.Sleep(2 * time.Millisecond)
	pool.Shutdown()
	wg.Wait() // should not hang
}
